// Auto-generated: seeds background images + config on first visit
const SEED_KEY = "kotori-seika-seeded-v2";
const SEED_IMAGES = {
  "bg_seed_0": "data:image/png;base64,",
  "bg_seed_1": "data:image/png;base64,",
};

const SEED_CONFIG = {
  musicIds: ["4949138"],
  subjectLinks: {
    "math-probability": { notebookLM: "https://notebooklm.google.com/notebook/e9f55d74-ca28-4df5-9a42-cc149362c4b2" },
    "math-ode": { notebookLM: "https://notebooklm.google.com/notebook/85b7fdfe-d8b7-4f7b-a90f-134499d43f33" },
    "physics-mech": { notebookLM: "https://notebooklm.google.com/notebook/e9f55d74-ca28-4df5-9a42-cc149362c4b2" },
    "cs-ics": { notebookLM: "https://notebooklm.google.com/notebook/2fc3274a-4750-43c3-9fd0-ca94c0f66166" }
  },
  backgrounds: ["bg_seed_0", "bg_seed_1"],
  currentBg: 0
};

async function seedData() {
  if (localStorage.getItem(SEED_KEY)) return;
  try {
    const req = indexedDB.open("kotori-seika-images", 1);
    req.onupgradeneeded = e => e.target.result.createObjectStore("images");
    req.onsuccess = async e => {
      const db = e.target.result;
      for (const [key, data] of Object.entries(SEED_IMAGES)) {
        await new Promise((resolve, reject) => {
          const tx = db.transaction("images", "readwrite");
          tx.objectStore("images").put(data, key);
          tx.oncomplete = resolve;
          tx.onerror = reject;
        });
      }
      // Merge config into existing state
      const raw = localStorage.getItem("kotori-seika-v1");
      const state = raw ? JSON.parse(raw) : {};
      // Music
      if (!state.settings) state.settings = {};
      if (!state.settings.musicIds || !state.settings.musicIds.length) {
        state.settings.musicIds = SEED_CONFIG.musicIds;
      }
      // Backgrounds
      if (!state.settings.backgrounds || !state.settings.backgrounds.length) {
        state.settings.backgrounds = SEED_CONFIG.backgrounds;
        state.settings.currentBg = SEED_CONFIG.currentBg;
      }
      // Subject links (merge, don't overwrite)
      if (!state.subjectLinks) state.subjectLinks = {};
      for (const [k, v] of Object.entries(SEED_CONFIG.subjectLinks)) {
        if (!state.subjectLinks[k] || !state.subjectLinks[k].notebookLM) {
          state.subjectLinks[k] = v;
        }
      }
      localStorage.setItem("kotori-seika-v1", JSON.stringify(state));
      localStorage.setItem(SEED_KEY, "1");
      console.log("Seed data loaded successfully");
    };
  } catch(e) { console.warn("Seed failed", e); }
}
seedData();
